            var uuid = function () {
              return ([1e7] + -1e3 + -4e3 + -8e3 + -1e11).replace(/[018]/g, function (x) {
                return (x ^ (c.getRandomValues(new Uint8Array(1))[0] & (15 >> (x / 4)))).toString(16);
              });
            };
            try { c.randomUUID = uuid; }
            catch (e) { Object.defineProperty(c, 'randomUUID', { value: uuid, configurable: true, writable: true }); }
          }
        } catch (e) {}
      })();

