(function () {
        var DONE = false;
        function lift() {
          var h = document.documentElement;
          h.classList.add('w-mod-ix3'); // lift Webflow's visibility:hidden gate
          document.querySelectorAll('.preloader').forEach(function (p) { p.style.display = 'none'; });
          document.querySelectorAll('.navbar-dropdown').forEach(function (d) { d.style.display = 'none'; });
          document.querySelectorAll('[style*="opacity"]').forEach(function (el) {
            if (parseFloat(el.style.opacity) === 0) el.style.opacity = '1';
          });
        }
        function animate() {
          var SEL = '.title-hero,.hero-video-wrap,.service-hero-item,.button-hero,.hero-top-sosmed-wrap,' +
                    '.title-section,.tag-section,.service-image,.card-project-hero,.about-us-element,' +
                    '.amount-card,.work-image,.work-button-wrap,.team-card,.testi-content-wrap,.testi-image,' +
                    '.client-card,.answer-block,.people-image-list,.heading-3,.service-text-wrap';
          var els = [].slice.call(document.querySelectorAll(SEL));
          els.forEach(function (el) {
            el.style.transition = 'opacity .7s cubic-bezier(.2,.6,.2,1), transform .7s cubic-bezier(.2,.6,.2,1)';
            el.style.opacity = '0';
            el.style.transform = 'translateY(28px)';
            el.setAttribute('data-wf-fb', '1');
          });
          function show(el, d) { setTimeout(function () { el.style.opacity = '1'; el.style.transform = 'none'; el.removeAttribute('data-wf-fb'); }, d || 0); }
          var vh = window.innerHeight || document.documentElement.clientHeight;
          if ('IntersectionObserver' in window) {
            var io = new IntersectionObserver(function (entries) {
              entries.forEach(function (e) { if (e.isIntersecting) { show(e.target, 0); io.unobserve(e.target); } });
            }, { threshold: 0.08, rootMargin: '0px 0px -8% 0px' });
            var n = 0;
            els.forEach(function (el) {
              var r = el.getBoundingClientRect();
              if (r.top < vh && r.bottom > 0) { show(el, (n++) * 70); }  // above the fold: staggered entrance
              else { io.observe(el); }                                   // below the fold: reveal on scroll
            });
          } else {
            els.forEach(function (el, i) { show(el, i * 40); });
          }
          // safety net: never leave anything hidden
          setTimeout(function () {
            document.querySelectorAll('[data-wf-fb]').forEach(function (el) { el.style.opacity = '1'; el.style.transform = 'none'; });
          }, 6000);
        }
        function run() { if (DONE) return; DONE = true; lift(); animate(); }
        var start = Date.now();
        var poll = setInterval(function () {
          if (document.documentElement.classList.contains('w-mod-ix3')) { clearInterval(poll); return; } // engine OK -> native animations
          if (Date.now() - start > 3500) { clearInterval(poll); run(); }                                 // engine dead -> fallback animations
        }, 200);
      })();
